#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minMoves(vector<int>& nums, int k) {
        vector<long long> p;
        for (int i = 0; i < nums.size(); ++i) {
            if (nums[i] == 1) {
                p.push_back(i - p.size());
            }
        }
        int m = p.size();
        vector<long long> pref(m + 1, 0);
        for (int i = 0; i < m; ++i) {
            pref[i + 1] = pref[i] + p[i];
        }
        long long ans = -1;
        for (int i = 0; i <= m - k; ++i) {
            int mid = i + k / 2;
            long long left_cost = p[mid] * (mid - i) - (pref[mid] - pref[i]);
            long long right_cost = (pref[i + k] - pref[mid + 1]) - p[mid] * (i + k - 1 - mid);
            long long cost = left_cost + right_cost;
            if (ans == -1 || cost < ans) ans = cost;
        }
        return (int)ans;
    }
};

import java.util.*;

class Solution {
    public int minMoves(int[] nums, int k) {
        List<Long> pList = new ArrayList<>();
        for (int i = 0; i < nums.length; ++i) {
            if (nums[i] == 1) {
                pList.add((long)i - pList.size());
            }
        }
        int m = pList.size();
        long[] pref = new long[m + 1];
        for (int i = 0; i < m; ++i) {
            pref[i + 1] = pref[i] + pList.get(i);
        }
        long ans = Long.MAX_VALUE;
        for (int i = 0; i <= m - k; ++i) {
            int mid = i + k / 2;
            long pMid = pList.get(mid);
            long leftCost = pMid * (mid - i) - (pref[mid] - pref[i]);
            long rightCost = (pref[i + k] - pref[mid + 1]) - pMid * (i + k - 1 - mid);
            ans = Math.min(ans, leftCost + rightCost);
        }
        return (int)ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var minMoves = function(nums, k) {
    const p = [];
    for (let i = 0; i < nums.length; ++i) {
        if (nums[i] === 1) {
            p.push(i - p.length);
        }
    }
    const m = p.length;
    const pref = Array(m + 1).fill(0);
    for (let i = 0; i < m; ++i) {
        pref[i + 1] = pref[i] + p[i];
    }
    let ans = Infinity;
    for (let i = 0; i <= m - k; ++i) {
        const mid = i + Math.floor(k / 2);
        const leftCost = p[mid] * (mid - i) - (pref[mid] - pref[i]);
        const rightCost = (pref[i + k] - pref[mid + 1]) - p[mid] * (i + k - 1 - mid);
        ans = Math.min(ans, leftCost + rightCost);
    }
    return ans;
};
